import csv, json
totals = {}
for row in csv.DictReader(open("input.csv")):
    totals[row["region"]] = round(totals.get(row["region"], 0) + float(row["amount"]), 2)
json.dump(totals, open("output.json", "w"))

import csv, json
units = {}
for row in csv.DictReader(open("input.csv")):
    units[row["product"]] = units.get(row["product"], 0) + int(row["units"])
json.dump(units, open("output.json", "w"))
